// --- Consumer test: declares the interaction + the fields it uses (by type) ---
function consumerTest() {
  // The consumer only specifies fields it actually reads, matched by TYPE.
  return {
    request: { method: 'GET', path: '/prices/42' },
    response: {
      status: 200,
      // 'matchers': assert the TYPE, the value is only an example
      body: {
        amount_cents: { match: 'integer', example: 1299 },
        currency: { match: 'regex', regex: '^[A-Z]{3}$', example: 'USD' }
      }
    }
  };
}

// Generate the pact file (a recording of the consumer's expectations)
function generatePact(interaction) {
  return {
    consumer: 'checkout-web',
    provider: 'pricing',
    interactions: [interaction]
  };
}

// --- Provider verification: replay the request, check ONLY the recorded fields ---
function matchesType(rule, actual) {
  if (rule.match === 'integer') return Number.isInteger(actual);
  if (rule.match === 'regex') return typeof actual === 'string' && new RegExp(rule.regex).test(actual);
  return false;
}

function verify(pact, providerResponse) {
  const i = pact.interactions[0];
  if (providerResponse.status !== i.response.status) return false;
  // Only check the fields the consumer recorded; extra provider fields are ignored.
  for (const key of Object.keys(i.response.body)) {
    const rule = i.response.body[key];
    if (!(key in providerResponse.body)) return false;
    if (!matchesType(rule, providerResponse.body[key])) return false;
  }
  return true;
}

const pact = generatePact(consumerTest());

// Provider returns a DIFFERENT currency value + an EXTRA field, same types:
const providerResponse = {
  status: 200,
  body: { amount_cents: 999, currency: 'EUR', loyalty_points: 50 }
};

console.log(verify(pact, providerResponse) ? 'PASS' : 'FAIL');
